// src/components/KnowYourCandidate.js
import React, { useState } from 'react';
import { GoogleGenerativeAI } from '@google/generative-ai';

const KnowYourCandidate = ({ user, language }) => {
  const [candidateInfo, setCandidateInfo] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [constituency, setConstituency] = useState(user?.constituency || '');

  // Initialize Gemini AI with correct configuration
  const genAI = new GoogleGenerativeAI('AIzaSyDAg9-I7KPUQFnLxV0d_Cy8KM44CEm6WdE');

  const fetchCandidateInfo = async () => {
    if (!constituency) {
      setError(language === 'hindi' 
        ? 'कृपया पहले अपना निर्वाचन क्षेत्र सेट करें' 
        : 'Please set your constituency first'
      );
      return;
    }

    setLoading(true);
    setError('');
    setCandidateInfo(null);

    try {
      console.log('Fetching AI data for:', constituency);
      
      // Try different available models
      // First, let's list available models to see what's working
      const availableModels = await genAI.listModels();
      console.log('Available models:', availableModels);
      
      // Use gemini-1.0-pro which is widely available
      const model = genAI.getGenerativeModel({ 
        model: "gemini-1.0-pro",
        generationConfig: {
          temperature: 0.7,
          topK: 40,
          topP: 0.95,
          maxOutputTokens: 2048,
        }
      });

      const prompt = `Provide detailed information about Lok Sabha 2024 election candidates for ${constituency} constituency in India. 
      Include 2-3 main candidates with their:
      - Full name (in both Hindi and English)
      - Political party
      - Educational background
      - Political experience
      - Key election promises (3-4 points)
      - Contact information (if available)
      
      Format the response as a valid JSON array. Example:
      [
        {
          "name": "Candidate Name in Hindi / English",
          "party": "Party Name in Hindi / English",
          "education": "Educational background",
          "experience": "Political experience",
          "promises": ["Promise 1", "Promise 2", "Promise 3"],
          "contact": "email@example.com | Twitter: @handle"
        }
      ]`;

      console.log('Sending request to Gemini AI...');
      
      const result = await model.generateContent(prompt);
      const response = await result.response;
      const text = response.text();
      
      console.log('Raw AI Response:', text);
      
      // Clean and parse the response
      let cleanedText = text.trim();
      
      // Remove markdown code blocks if present
      cleanedText = cleanedText.replace(/```json/g, '').replace(/```/g, '').trim();
      
      // Extract JSON from the response
      const jsonStart = cleanedText.indexOf('[');
      const jsonEnd = cleanedText.lastIndexOf(']') + 1;
      
      if (jsonStart !== -1 && jsonEnd !== -1) {
        const jsonString = cleanedText.substring(jsonStart, jsonEnd);
        const candidates = JSON.parse(jsonString);
        
        console.log('Successfully parsed candidates:', candidates);
        
        // Filter based on search query
        const filteredCandidates = searchQuery 
          ? candidates.filter(candidate => 
              candidate.name && candidate.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
              candidate.party && candidate.party.toLowerCase().includes(searchQuery.toLowerCase())
            )
          : candidates;
          
        setCandidateInfo(filteredCandidates);
      } else {
        throw new Error('No valid JSON found in AI response');
      }
      
      setLoading(false);
      
    } catch (error) {
      console.error('Gemini AI Error:', error);
      
      // Try alternative model if first one fails
      if (error.message.includes('404') || error.message.includes('not found')) {
        console.log('Trying alternative model...');
        try {
          await tryAlternativeModel(constituency);
        } catch (secondError) {
          setError(language === 'hindi' 
            ? 'AI सेवा उपलब्ध नहीं है। कृपया बाद में पुनः प्रयास करें' 
            : 'AI service unavailable. Please try again later'
          );
        }
      } else {
        setError(language === 'hindi' 
          ? `AI सेवा में समस्या: ${error.message}` 
          : `AI service issue: ${error.message}`
        );
      }
      setLoading(false);
    }
  };

  const tryAlternativeModel = async (constituency) => {
    try {
      // Try gemini-pro with different endpoint
      const model = genAI.getGenerativeModel({ 
        model: "gemini-pro",
        generationConfig: {
          temperature: 0.7,
          maxOutputTokens: 2048,
        }
      });

      const prompt = `Give me candidate information for ${constituency} constituency in JSON format.`;
      
      const result = await model.generateContent(prompt);
      const response = await result.response;
      const text = response.text();
      
      console.log('Alternative model response:', text);
      
      // Process the response...
      let cleanedText = text.trim().replace(/```json/g, '').replace(/```/g, '').trim();
      const jsonStart = cleanedText.indexOf('[');
      const jsonEnd = cleanedText.lastIndexOf(']') + 1;
      
      if (jsonStart !== -1 && jsonEnd !== -1) {
        const jsonString = cleanedText.substring(jsonStart, jsonEnd);
        const candidates = JSON.parse(jsonString);
        setCandidateInfo(candidates);
      }
      
    } catch (error) {
      console.error('Alternative model also failed:', error);
      throw error;
    }
  };

  // Simple test function to check API connectivity
  const testAPI = async () => {
    try {
      console.log('Testing API connectivity...');
      const model = genAI.getGenerativeModel({ model: "gemini-pro" });
      const result = await model.generateContent('Say "API is working" in JSON format: {"status": "working"}');
      const response = await result.response;
      console.log('API Test Response:', response.text());
      return true;
    } catch (error) {
      console.error('API Test Failed:', error);
      return false;
    }
  };

  const handleSearch = (e) => {
    e.preventDefault();
    if (constituency) {
      // Test API first
      testAPI().then(isWorking => {
        if (isWorking) {
          fetchCandidateInfo();
        } else {
          setError(language === 'hindi' 
            ? 'API कनेक्शन विफल। कृपया API key और इंटरनेट कनेक्शन जांचें' 
            : 'API connection failed. Please check API key and internet connection'
          );
        }
      });
    }
  };

  const handleConstituencySelect = (e) => {
    setConstituency(e.target.value);
    setError('');
    setCandidateInfo(null);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && constituency) {
      handleSearch(e);
    }
  };

  const translations = {
    hindi: {
      title: "अपने उम्मीदवार को जानें",
      searchPlaceholder: "उम्मीदवार का नाम या पार्टी खोजें...",
      searchButton: "खोजें",
      selectConstituency: "अपना निर्वाचन क्षेत्र चुनें",
      constituency: "आपका निर्वाचन क्षेत्र",
      fetchButton: "उम्मीदवार जानकारी प्राप्त करें",
      loading: "AI डेटा लोड हो रहा है...",
      candidateInfo: "उम्मीदवार की जानकारी",
      name: "नाम",
      party: "पार्टी",
      education: "शिक्षा",
      experience: "राजनीतिक अनुभव",
      promises: "वादे और घोषणापत्र",
      contact: "संपर्क",
      noConstituency: "कृपया पहले अपना निर्वाचन क्षेत्र सेट करें",
      aiPowered: "यह जानकारी Google Gemini AI द्वारा प्रदान की गई है",
      noCandidates: "कोई उम्मीदवार नहीं मिले",
      liveData: "रियल-टाइम AI डेटा लोड हो रहा है...",
      searchResults: "खोज परिणाम",
      realTimeInfo: "रियल-टाइम जानकारी"
    },
    english: {
      title: "Know Your Candidate",
      searchPlaceholder: "Search candidate name or party...",
      searchButton: "Search",
      selectConstituency: "Select Your Constituency",
      constituency: "Your Constituency",
      fetchButton: "Get Candidate Info",
      loading: "Loading AI data...",
      candidateInfo: "Candidate Information",
      name: "Name",
      party: "Party",
      education: "Education",
      experience: "Political Experience",
      promises: "Promises & Manifesto",
      contact: "Contact",
      noConstituency: "Please set your constituency first",
      aiPowered: "This information is provided by Google Gemini AI",
      noCandidates: "No candidates found",
      liveData: "Loading real-time AI data...",
      searchResults: "Search Results",
      realTimeInfo: "Real-time Information"
    }
  };

  const t = translations[language];

  const constituencies = [
    "Amethi", "Rae Bareli", "Varanasi", "Lucknow", "Kanpur", 
    "Ghaziabad", "Prayagraj", "Gorakhpur", "Agra", "Meerut",
    "Delhi South", "Mumbai North", "Bangalore South", "Chennai Central", 
    "Hyderabad", "Kolkata North", "Ahmedabad East", "Pune", "Jaipur", "Chandigarh"
  ];

  return (
    <div className="know-your-candidate">
      <div className="candidate-header">
        <h2>{t.title}</h2>
        <div className="ai-badge">AI Powered</div>
      </div>
      
      <div className="constituency-selection">
        <div className="selection-card">
          <h4>📍 {t.selectConstituency}</h4>
          <select 
            value={constituency} 
            onChange={handleConstituencySelect}
            className="constituency-select"
          >
            <option value="">-- {t.selectConstituency} --</option>
            {constituencies.map((constituencyName, index) => (
              <option key={index} value={constituencyName}>
                {constituencyName}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="search-section">
        <div className="search-box">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder={t.searchPlaceholder}
            className="search-input"
          />
          <button 
            className="search-button" 
            onClick={handleSearch}
            disabled={!constituency || loading}
          >
            {t.searchButton}
          </button>
        </div>
      </div>

      {constituency && (
        <div className="constituency-info">
          <div className="info-card">
            <h4>🎯 {t.constituency}</h4>
            <p className="constituency-name">{constituency}</p>
            <div className="real-time-badge">
              <span className="live-dot"></span>
              {t.realTimeInfo}
            </div>
          </div>
        </div>
      )}

      <div className="action-section">
        <button 
          onClick={handleSearch}
          className="fetch-button"
          disabled={loading || !constituency}
        >
          {loading ? (
            <div className="button-loading">
              <span className="spinner"></span>
              {t.liveData}
            </div>
          ) : (
            t.fetchButton
          )}
        </button>
      </div>

      {error && (
        <div className="error-message">
          <div className="error-icon">⚠️</div>
          <p>{error}</p>
        </div>
      )}

      {candidateInfo && (
        <div className="candidates-list">
          <div className="ai-notice">
            <div className="ai-icon">✨</div>
            <div>
              <p><strong>{t.aiPowered}</strong></p>
              <small>{constituency} - {new Date().toLocaleDateString()}</small>
            </div>
          </div>
          
          <h3>
            {t.candidateInfo} - {constituency}
            {searchQuery && (
              <span className="search-results-badge"> ({t.searchResults}: "{searchQuery}")</span>
            )}
          </h3>
          
          {candidateInfo.length === 0 ? (
            <div className="no-candidates">
              <p>{t.noCandidates}</p>
            </div>
          ) : (
            <div className="candidates-grid">
              {candidateInfo.map((candidate, index) => (
                <div key={index} className="candidate-card">
                  <div className="candidate-header-card">
                    <div className="candidate-avatar">
                      {candidate.name ? candidate.name.charAt(0) : '?'}
                    </div>
                    <div className="candidate-basic-info">
                      <h4>{candidate.name || 'Unknown Candidate'}</h4>
                      <span className="party-badge">{candidate.party || 'Unknown Party'}</span>
                    </div>
                  </div>
                  
                  <div className="candidate-details">
                    <div className="detail-item">
                      <span className="detail-label">🎓 {t.education}:</span>
                      <span className="detail-value">{candidate.education || 'Not specified'}</span>
                    </div>
                    
                    <div className="detail-item">
                      <span className="detail-label">💼 {t.experience}:</span>
                      <span className="detail-value">{candidate.experience || 'Not specified'}</span>
                    </div>
                    
                    {candidate.contact && (
                      <div className="detail-item">
                        <span className="detail-label">📞 {t.contact}:</span>
                        <span className="detail-value">{candidate.contact}</span>
                      </div>
                    )}
                  </div>

                  <div className="promises-section">
                    <h5>📋 {t.promises}:</h5>
                    <ul className="promises-list">
                      {candidate.promises && candidate.promises.map((promise, promiseIndex) => (
                        <li key={promiseIndex} className="promise-item">
                          <span className="promise-icon">✓</span>
                          {promise}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default KnowYourCandidate;
